--------------------
-- Flu_status  
-- One year look-back prior to event_date
-- 1 = flu vaccine received, 0 = not received
--------------------

WITH flu_events AS (
    SELECT
        P.Patient_ID,
        P.infect,
        P.event_date,
        med.MedicationDate AS flu_date
    FROM [BRIT].[PatientLevelData] P
    INNER JOIN [BRIT].[patient_link] pl
        ON P.Patient_ID = pl.PK_Patient_Link_ID
    INNER JOIN BRIT.GP_Medications med
        ON med.FK_Patient_Link_ID = pl.PK_Patient_Link_ID
    WHERE
        med.MedicationDate BETWEEN DATEADD(YEAR, -1, P.event_date)
                               AND P.event_date
        AND med.SuppliedCode IN (
            '1002111000001102','38973511000001106','38969911000001109',
            '38970011000001108','40085311000001103','40085411000001105',
            '40085611000001108','37531311000001101','37513211000001101',
            '37513511000001103','37547211000001103','37547411000001104',
            '37547311000001106','43207711000001104','43207811000001107',
            '43207911000001102','3255311000001102','3255411000001109',
            '4029011000001109','3247011000001105','3247211000001100',
            '3247511000001102','40085011000001101','40085211000001106',
            '40085111000001100','43207411000001105','43207511000001109',
            '43207611000001108','15650611000001107','15650711000001103',
            '9511411000001107','9511511000001106','9511611000001105',
            '38973211000001108','38973411000001107','38972311000001105',
            '37514711000001105','37514911000001107','37514811000001102',
            '22704311000001109','25256511000001107','22704411000001102',
            '3245911000001104','3246211000001102','3246411000001103',
            '39121211000001109','39121311000001101','39121411000001108',
            '36509011000001106','36509111000001107','36510911000001101',
            '43208811000001106','43209311000001108','27114211000001105',
            '27114311000001102','19820511000001106','19840411000001105',
            '30935711000001104','30935811000001107','3249511000001109',
            '3251211000001107','3251011000001102','4644211000001108',
            '4644411000001107','10859911000001105','10860111000001108',
            '10860011000001107','10306611000001101','10306711000001105',
            '10306811000001102','15651211000001104','15650911000001101',
            '15651311000001107','15650011000001100','35727411000001104',
            '35727511000001100','35727611000001101','35726811000001104',
            '35727011000001108','35726911000001109','15507511000001109',
            '15506411000001108','20450511000001103','15474011000001107',
            '15454411000001100','36755311000001100','36754011000001102',
            '9519711000001102','9509111000001100','9509211000001106',
            '9509311000001103','39716811000001100','3243711000001102',
            '3244111000001101','10133911000001103','10134011000001100',
            '35031411000001107','11278411000001109','21146511000001108',
            '11278511000001108','3244411000001106','3244811000001108',
            '3245611000001105','42894611000001103','42893211000001103',
            '39716611000001104','3249011000001101','3249211000001106',
            '3252611000001103','3252911000001109','3252711000001107',
            '10309511000001105','10306211000001103','10306311000001106',
            '22628411000001107','22628511000001106','22628611000001105',
            '35727111000001109','35727311000001106','35727211000001103',
            '3255011000001100','3255211000001105','3255111000001104',
            '15506511000001107','15506611000001106','20450611000001104',
            '15454511000001101','15454611000001102','10306411000001104',
            '10306511000001100','4365711000001104','4365911000001102',
            '4365811000001107','9903711000001109','9903811000001101',
            '15382311000001101','15382411000001108','23445511000001105',
            '20292211000001109','20292311000001101','19821411000001103',
            '19840311000001103','39126711000001108','39121011000001104',
            '39121111000001103','42893311000001106','42893411000001104',
            '34680411000001107','34680511000001106','34680611000001105',
            '43292711000001104','43208711000001103','36754111000001101',
            '36754211000001107','43208311000001102','43207211000001106',
            '43207311000001103','10455811000001107','10455911000001102',
            '10456011000001105','884861000000100','884881000000109',
            '985151000000100','945831000000105','955651000000100',
            '955661000000102','955671000000109','955681000000106',
            '955691000000108','955701000000108','1037311000000100',
            '1037331000000100','1037351000000100','1037371000000100',
            '1066171000000100','1066181000000100','1066191000000100',
            '1239861000000100','985171000000109'
        )
),
flu_flag AS (
    SELECT
        Patient_ID,
        infect,
        event_date,
        1 AS Flu_status
    FROM flu_events
    GROUP BY Patient_ID, infect, event_date
)
UPDATE [BRIT].[PatientLevelData]
SET Flu_status = 1
FROM [BRIT].[PatientLevelData]
INNER JOIN flu_flag ff
    ON ff.Patient_ID = [BRIT].[PatientLevelData].Patient_ID
   AND ff.infect = [BRIT].[PatientLevelData].infect
   AND ff.event_date = [BRIT].[PatientLevelData].event_date;
